def _get_domain_header(rules):
    """Determine the appropriate header for domain information."""
    # Check if any rule has a host
    if any(rule.host for rule in rules):
        return "Host"
    # Check if any rule has a subdomain
    if any(rule.subdomain for rule in rules):
        return "Subdomain"
    return "Domain"


